package com.fintrack.khmtomnenh.order.entity; import com.fasterxml.jackson.annotation.*; import com.fintrack.khmtomnenh.auth.entity.Auth; import com.fintrack.khmtomnenh.quotation.entity.Quotation; import com.fintrack.khmtomnenh.orderitem.entity.OrderItem; import jakarta.persistence.*; import lombok.*; import java.math.*; import java.time.*; import java.util.*; import org.hibernate.annotations.CreationTimestamp; import org.hibernate.annotations.UpdateTimestamp;
@Entity @Table(name="orders") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class Order {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @JsonIgnore @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="buyer_id") private Auth buyer; @JsonIgnore @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="supplier_id") private Auth supplier; @JsonIgnore @OneToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="quotation_id",unique=true) private Quotation quotation; @Column(nullable=false,precision=19,scale=2) private BigDecimal totalAmount; @Builder.Default @Column(nullable=false) private String status="PENDING"; @CreationTimestamp @Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt; @UpdateTimestamp private LocalDateTime updatedAt; @JsonManagedReference @OneToMany(mappedBy="order",cascade=CascadeType.ALL,orphanRemoval=true) @Builder.Default private List<OrderItem> items=new ArrayList<>();}
